import inspect

def namesAndDescriptions(self, all=False):
    attrs = {}
    for name, obj in inspect.getmembers(self.__class__):
        if name.startswith('_'):
            continue
        if isinstance(obj, property):
            desc = obj.__doc__ or ""
            attrs[name] = desc
        elif not inspect.isroutine(obj):
            desc = getattr(obj, "__doc__", "") or ""
            attrs[name] = desc
    if all:
        # include methods
        for name, obj in inspect.getmembers(self.__class__):
            if name.startswith('_'):
                continue
            if inspect.isroutine(obj):
                desc = getattr(obj, "__doc__", "") or ""
                attrs[name] = desc
    return attrs
```

