def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, value) tuples, deep merging MappingNode values.
    """
    def merge_mapping_nodes(node1, node2):
        # node1 and node2 are MappingNode instances
        merged = {}
        for key, val in node1.value:
            merged[key.value] = (key, val)
        for key, val in node2.value:
            if key.value in merged:
                _, existing_val = merged[key.value]
                if isinstance(existing_val, MappingNode) and isinstance(val, MappingNode):
                    merged[key.value] = (key, merge_mapping_nodes(existing_val, val))
                else:
                    merged[key.value] = (key, val)
            else:
                merged[key.value] = (key, val)
        return MappingNode(tag='tag:yaml.org,2002:map', value=list(merged.values()))

