import yaml
from pathlib import Path
from typing import Any, Dict

def get_plugin_spec_flatten_dict(plugin_dir: str | Path) -> Dict[str, Any]:
    """
    Creates a flat dict from the plugin spec.

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_path = Path(plugin_dir)
    spec_file = None
    for ext in (".yaml", ".yml", ".json"):
        candidate = plugin_path / f"plugin{ext}"
        if candidate.is_file():
            spec_file = candidate
            break
    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    if spec_file.suffix in {".yaml", ".yml"}:
        with spec_file.open("r", encoding="utf-8") as f:
            spec = yaml.safe_load(f)
    else:
        with spec_file.open("r", encoding="utf-8") as f:
            spec = json.load(f)

    def _flatten(d: Dict[str, Any], parent_key: str = "", sep: str = ".") -> Dict[str, Any]:
        items: Dict[str, Any] = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    if not isinstance(spec, dict):
        raise ValueError("Plugin spec must be a dictionary at the top level")

    return _flatten(spec)

